// Browser-local demonstration adapter. This is not an authorization boundary.
esc=function(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
const demoOriginalRender=renderPreview;
renderPreview=function(){demoOriginalRender();document.getElementById('preview').insertAdjacentHTML('afterbegin','<div class="demo-watermark">DEMONSTRATION ONLY · NOT A VALID COMMERCIAL QUOTATION</div>')};
window.demoLoad=function(data){ITEMS=JSON.parse(JSON.stringify(data.items));CHASSIS.splice(0,CHASSIS.length,...data.chassis);FREIGHT_ESTIMATES.splice(0,FREIGHT_ESTIMATES.length,...data.freight);Object.assign(state,data.state);const m=document.getElementById('model');m.replaceChildren(...ITEMS.filter(i=>i.isBase).map(i=>new Option(i.model,i.model)));const rep=document.getElementById('salesRep');rep.replaceChildren(new Option(state.salesRep,state.salesRep));rep.disabled=true;const mapping={quoteDate:'date',model:'model',basis:'basis',po:'po',fob:'fob',acct:'acct',salesRep:'salesRep',toCompany:'toCompany',toContact:'toContact',toAddr1:'toAddr1',toAddr2:'toAddr2',baseQty:'baseQty',baseShowDiscount:'baseShowDiscount',quoteSeq:'quoteSeq'};for(const [id,key] of Object.entries(mapping)){const el=document.getElementById(id);if(el&&state[key]!==undefined)el.value=state[key];}document.getElementById('quoteSeq').readOnly=true;document.getElementById('quoteDate').removeAttribute('min');render();if(data.state.freight!==undefined){state.freight=data.state.freight;document.getElementById('freight').value=state.freight;renderPreview()}if(data.readonly){document.querySelectorAll('.builder input,.builder select').forEach(el=>el.disabled=true);document.querySelector('.brandbar h1').textContent='Finalized quotation';}};
window.demoSnapshot=function(){let base=priceForItem(baseItem(state.model));let total=state.baseQty*base.unit+Number(state.freight||0);for(const row of state.enh){const item=enhOptions(state.model).find(x=>x.desc===row.desc);if(item)total+=row.qty*priceForItem(item).unit;}return JSON.parse(JSON.stringify({state,catalog:ITEMS,chassis:CHASSIS,freight:FREIGHT_ESTIMATES,total}))};
document.querySelectorAll('label').forEach(label=>{if(!label.htmlFor){const input=label.parentElement.querySelector('input,select');if(input?.id)label.htmlFor=input.id;}});
renderPreview();
